<template><ion-page><DetailHeader title="灵感详情" default-href="/inspirations"><template #action><button type="button" class="header-action" aria-label="编辑灵感" @click="router.push({name:'inspiration-edit',params:{inspirationId:item?.id}})"><Pencil :size="20"/></button></template></DetailHeader><ion-content class="page-content"><main class="page-shell detail-shell"><FeedSkeleton v-if="loading" :count="2"/><StatePanel v-else-if="!item" tone="error" title="找不到这条灵感" description="它可能已被归档。"/><template v-else><span class="status">{{item.status==='draft'?'草稿':'已保存'}}</span><h1>{{item.title}}</h1><p v-if="item.summary" class="summary">{{item.summary}}</p><div class="tag-list"><span v-for="tag in item.tags" :key="tag" class="tag">{{tag}}</span></div><section class="content"><template v-for="(block,index) in item.content" :key="index"><img v-if="block.type==='image'" :src="resolveMediaUrl(block.url)" :alt="block.alt||item.title" loading="lazy"/><p v-else>{{block.text}}</p></template></section><section v-if="item.location_name" class="location"><MapPin :size="20"/><div><strong>{{item.location_name}}</strong><span>{{item.location_address}}</span></div></section></template></main></ion-content></ion-page></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {IonContent,IonPage} from '@ionic/vue';import {MapPin,Pencil} from 'lucide-vue-next';import DetailHeader from '@/components/DetailHeader.vue';import FeedSkeleton from '@/components/FeedSkeleton.vue';import StatePanel from '@/components/StatePanel.vue';import {getInspiration} from '@/api/inspirations';import type {Inspiration} from '@/types/inspiration';import {resolveMediaUrl} from '@/utils/media';const route=useRoute(),router=useRouter(),item=ref<Inspiration|null>(null),loading=ref(true);onMounted(async()=>{try{item.value=await getInspiration(Number(route.params.inspirationId))}finally{loading.value=false}})</script>
<style scoped>.detail-shell{padding-top:var(--space-5);padding-bottom:calc(var(--bottom-nav-height) + 40px)}.status{display:inline-flex;min-height:28px;align-items:center;padding:4px 10px;border-radius:var(--radius-pill);background:var(--brand-soft);color:var(--brand);font-size:var(--text-xs);font-weight:800}.detail-shell h1{margin:var(--space-3) 0 var(--space-2);font-family:var(--font-serif);font-size:var(--text-2xl);line-height:1.25}.summary{margin:0;color:var(--ink-secondary);font-size:var(--text-base);line-height:1.7}.tag-list{display:flex;flex-wrap:wrap;gap:8px;margin:var(--space-4) 0}.content{display:grid;gap:18px;margin-top:var(--space-6)}.content p{margin:0;color:var(--ink);font-size:var(--text-base);line-height:1.85;white-space:pre-wrap}.content img{width:100%;border-radius:var(--radius-md);box-shadow:var(--shadow-1)}.location{display:flex;gap:10px;margin-top:var(--space-6);padding:14px;border-radius:var(--radius-md);background:var(--brand-soft);color:var(--brand)}.location div{display:grid}.location span{color:var(--ink-secondary);font-size:var(--text-xs)}</style>
